import { useEffect, useRef } from 'react';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Highlight from '@tiptap/extension-highlight';
import Typography from '@tiptap/extension-typography';
import Image from '@tiptap/extension-image';
import { Markdown, type MarkdownStorage } from 'tiptap-markdown';
import { cn } from '../lib/utils';
import { MarkdownEditorToolbar } from './MarkdownEditorToolbar';

import '../markdown/markdown.css';

declare module '@tiptap/core' {
  interface Storage {
    markdown: MarkdownStorage;
  }
}

export interface MarkdownEditorProps {
  /** Initial markdown content to populate the editor with. */
  content?: string;
  /** Callback fired on every change, receiving the current markdown string. */
  onChange?: (markdown: string) => void;
  /** Additional class names applied to the outer wrapper element. */
  className?: string;
  /** Additional class names applied to the editor content area. */
  editorClassName?: string;
  /**
   * Whether the editor content is editable. When `false`, the toolbar is hidden.
   * @default true
   */
  editable?: boolean;
  /** Hide the bold button from the toolbar. */
  hideBold?: boolean;
  /** Hide the italic button from the toolbar. */
  hideItalic?: boolean;
  /** Hide the strikethrough button from the toolbar. */
  hideStrikethrough?: boolean;
  /** Hide the inline code button from the toolbar. */
  hideCode?: boolean;
  /** Hide the highlight button from the toolbar. */
  hideHighlight?: boolean;
  /** Hide the heading buttons (H1, H2, H3) from the toolbar. */
  hideHeadings?: boolean;
  /** Hide the bullet list button from the toolbar. */
  hideBulletList?: boolean;
  /** Hide the ordered list button from the toolbar. */
  hideOrderedList?: boolean;
  /** Hide the blockquote button from the toolbar. */
  hideBlockquote?: boolean;
  /** Hide the horizontal rule button from the toolbar. */
  hideHorizontalRule?: boolean;
  /** Hide the undo/redo buttons from the toolbar. */
  hideUndoRedo?: boolean;
  /**
   * Controls the editor height. Fixed values (`sm`, `md`, `lg`) set a fixed height.
   * Dynamic values (`dynamic-sm`, `dynamic-md`, `dynamic-lg`) set a minimum height
   * that grows with content.
   * @default "dynamic-md"
   */
  height?: 'sm' | 'md' | 'lg' | 'dynamic-sm' | 'dynamic-md' | 'dynamic-lg';
}

/**
 * A rich text / markdown editor built on TipTap. Use this whenever the user
 * needs to write or edit formatted text. The editor returns markdown via
 * `onChange` and accepts markdown as `content`.
 *
 * Storage: if you need to persist rich text in a Zite database, use the
 * `rich_text` field type for that field — it stores markdown directly.
 *
 * Styling: the editor renders its own border, shadow, and focus ring. Do NOT
 * wrap it in another bordered/shadowed container — you'll get double borders.
 *
 * Read-only rendering: for displaying markdown without an editor, import
 * `Markdown` from `@/components/markdown` instead. Don't pass `editable={false}`
 * here for static content — it still mounts a full TipTap instance.
 *
 * DO NOT build your own rich text editor. DO NOT swap in a different library
 * (Lexical, Slate, Quill, etc.). Use this component.
 *
 * @example
 * ```tsx
 * import { MarkdownEditor } from './'
 *
 * <MarkdownEditor
 *   content="**Hello** world"
 *   onChange={(markdown) => setNotes(markdown)}
 * />
 * ```
 *
 * @example Hide specific toolbar buttons:
 * ```tsx
 * <MarkdownEditor hideHeadings hideBlockquote hideHorizontalRule />
 * ```
 *
 * @example Read-only with toolbar hidden:
 * ```tsx
 * <MarkdownEditor content={notes} editable={false} />
 * ```
 */
export function MarkdownEditor({
  content = '',
  onChange,
  className,
  editorClassName,
  editable = true,
  hideBold,
  hideItalic,
  hideStrikethrough,
  hideCode,
  hideHighlight,
  hideHeadings,
  hideBulletList,
  hideOrderedList,
  hideBlockquote,
  hideHorizontalRule,
  hideUndoRedo,
  height = 'dynamic-md',
}: MarkdownEditorProps) {
  const valueRef = useRef(content);
  const editor = useEditor({
    extensions: [StarterKit, Highlight, Typography, Image, Markdown],
    content,
    editable,
    onUpdate: ({ editor }) => {
      const markdown = editor.storage.markdown.getMarkdown();
      valueRef.current = markdown;
      onChange?.(markdown);
    },
  });

  useEffect(() => {
    if (editor && content !== valueRef.current) {
      editor.commands.setContent(content, { emitUpdate: false });
    }
  }, [content, editor]);

  if (!editor) {
    return null;
  }

  return (
    <div
      className={cn(
        'rounded-md border border-input bg-transparent shadow-sm focus-within:ring-1 focus-visible:outline-none focus-within:ring-ring',
        className,
      )}
    >
      {editable && (
        <MarkdownEditorToolbar
          editor={editor}
          hideBold={hideBold}
          hideItalic={hideItalic}
          hideStrikethrough={hideStrikethrough}
          hideCode={hideCode}
          hideHighlight={hideHighlight}
          hideHeadings={hideHeadings}
          hideBulletList={hideBulletList}
          hideOrderedList={hideOrderedList}
          hideBlockquote={hideBlockquote}
          hideHorizontalRule={hideHorizontalRule}
          hideUndoRedo={hideUndoRedo}
        />
      )}
      <EditorContent
        editor={editor}
        className={cn(
          'flex flex-col [&_.tiptap]:flex-1 text-base prose prose-sm max-w-none p-4 overflow-y-auto focus-within:outline-none [&_.tiptap]:outline-none [&_.tiptap>:first-child]:mt-0',
          {
            'h-32': height === 'sm',
            'h-64': height === 'md',
            'h-96': height === 'lg',
          },
          {
            'min-h-32': height === 'dynamic-sm',
            'min-h-64': height === 'dynamic-md',
            'min-h-96': height === 'dynamic-lg',
          },
          editorClassName,
        )}
      />
    </div>
  );
}

import { useEditorState, type Editor } from '@tiptap/react';
import {
  Bold,
  Italic,
  Strikethrough,
  Code,
  Heading1,
  Heading2,
  Heading3,
  List,
  ListOrdered,
  Quote,
  Minus,
  Undo,
  Redo,
  Highlighter,
} from 'lucide-react';
import { Toggle } from '../ui/toggle';
import { Separator } from '../ui/separator';

interface MarkdownEditorToolbarProps {
  editor: Editor;
  hideBold?: boolean;
  hideItalic?: boolean;
  hideStrikethrough?: boolean;
  hideCode?: boolean;
  hideHighlight?: boolean;
  hideHeadings?: boolean;
  hideBulletList?: boolean;
  hideOrderedList?: boolean;
  hideBlockquote?: boolean;
  hideHorizontalRule?: boolean;
  hideUndoRedo?: boolean;
}

function ToolbarToggle({
  pressed,
  onPressedChange,
  disabled,
  children,
  title,
}: {
  pressed: boolean;
  onPressedChange: () => void;
  disabled?: boolean;
  children: React.ReactNode;
  title: string;
}) {
  return (
    <Toggle
      size="sm"
      pressed={pressed}
      onPressedChange={onPressedChange}
      disabled={disabled}
      aria-label={title}
      title={title}
    >
      {children}
    </Toggle>
  );
}

function ToolbarButton({
  onClick,
  disabled,
  children,
  title,
}: {
  onClick: () => void;
  disabled?: boolean;
  children: React.ReactNode;
  title: string;
}) {
  return (
    <Toggle
      size="sm"
      pressed={false}
      onPressedChange={onClick}
      disabled={disabled}
      aria-label={title}
      title={title}
    >
      {children}
    </Toggle>
  );
}

export function MarkdownEditorToolbar({
  editor,
  hideBold,
  hideItalic,
  hideStrikethrough,
  hideCode,
  hideHighlight,
  hideHeadings,
  hideBulletList,
  hideOrderedList,
  hideBlockquote,
  hideHorizontalRule,
  hideUndoRedo,
}: MarkdownEditorToolbarProps) {
  const showInlineSection =
    !hideBold ||
    !hideItalic ||
    !hideStrikethrough ||
    !hideCode ||
    !hideHighlight;
  const showHeadingsSection = !hideHeadings;
  const showBlockSection =
    !hideBulletList ||
    !hideOrderedList ||
    !hideBlockquote ||
    !hideHorizontalRule;
  const showUndoRedoSection = !hideUndoRedo;

  const editorState = useEditorState({
    editor,
    selector(ctx) {
      return {
        // Text formatting
        isBold: ctx.editor.isActive('bold') ?? false,
        canBold: ctx.editor.can().chain().toggleBold().run() ?? false,
        isItalic: ctx.editor.isActive('italic') ?? false,
        canItalic: ctx.editor.can().chain().toggleItalic().run() ?? false,
        isStrike: ctx.editor.isActive('strike') ?? false,
        canStrike: ctx.editor.can().chain().toggleStrike().run() ?? false,
        isCode: ctx.editor.isActive('code') ?? false,
        canCode: ctx.editor.can().chain().toggleCode().run() ?? false,
        isHighlight: ctx.editor.isActive('highlight') ?? false,
        canHighlight: ctx.editor.can().chain().toggleHighlight().run() ?? false,

        // Block types
        isParagraph: ctx.editor.isActive('paragraph') ?? false,
        isHeading1: ctx.editor.isActive('heading', { level: 1 }) ?? false,
        canHeading1:
          ctx.editor.can().chain().toggleHeading({ level: 1 }).run() ?? false,
        isHeading2: ctx.editor.isActive('heading', { level: 2 }) ?? false,
        canHeading2:
          ctx.editor.can().chain().toggleHeading({ level: 2 }).run() ?? false,
        isHeading3: ctx.editor.isActive('heading', { level: 3 }) ?? false,
        canHeading3:
          ctx.editor.can().chain().toggleHeading({ level: 3 }).run() ?? false,

        // Lists and blocks
        isBulletList: ctx.editor.isActive('bulletList') ?? false,
        canBulletList:
          ctx.editor.can().chain().toggleBulletList().run() ?? false,
        isOrderedList: ctx.editor.isActive('orderedList') ?? false,
        canOrderedList:
          ctx.editor.can().chain().toggleOrderedList().run() ?? false,
        isCodeBlock: ctx.editor.isActive('codeBlock') ?? false,
        isBlockquote: ctx.editor.isActive('blockquote') ?? false,
        canBlockquote:
          ctx.editor.can().chain().toggleBlockquote().run() ?? false,
        canHorizontalRule:
          ctx.editor.can().chain().setHorizontalRule().run() ?? false,

        // History
        canUndo: ctx.editor.can().chain().undo().run() ?? false,
        canRedo: ctx.editor.can().chain().redo().run() ?? false,
      };
    },
  });

  if (
    !showInlineSection &&
    !showHeadingsSection &&
    !showBlockSection &&
    !showUndoRedoSection
  ) {
    return null;
  }

  return (
    <div className="flex flex-wrap items-center gap-0.5 border-b border-input p-1 px-[max(calc(var(--radius)-1.5rem),0.25rem)]">
      {showInlineSection && (
        <>
          {!hideBold && (
            <ToolbarToggle
              pressed={editorState.isBold}
              disabled={!editorState.canBold}
              onPressedChange={() => editor.chain().focus().toggleBold().run()}
              title="Bold"
            >
              <Bold className="size-4" />
            </ToolbarToggle>
          )}
          {!hideItalic && (
            <ToolbarToggle
              pressed={editorState.isItalic}
              disabled={!editorState.canItalic}
              onPressedChange={() =>
                editor.chain().focus().toggleItalic().run()
              }
              title="Italic"
            >
              <Italic className="size-4" />
            </ToolbarToggle>
          )}
          {!hideStrikethrough && (
            <ToolbarToggle
              pressed={editorState.isStrike}
              disabled={!editorState.canStrike}
              onPressedChange={() =>
                editor.chain().focus().toggleStrike().run()
              }
              title="Strikethrough"
            >
              <Strikethrough className="size-4" />
            </ToolbarToggle>
          )}
          {!hideCode && (
            <ToolbarToggle
              pressed={editorState.isCode}
              disabled={!editorState.canCode}
              onPressedChange={() => editor.chain().focus().toggleCode().run()}
              title="Inline code"
            >
              <Code className="size-4" />
            </ToolbarToggle>
          )}
          {!hideHighlight && (
            <ToolbarToggle
              pressed={editorState.isHighlight}
              disabled={!editorState.canHighlight}
              onPressedChange={() =>
                editor.chain().focus().toggleHighlight().run()
              }
              title="Highlight"
            >
              <Highlighter className="size-4" />
            </ToolbarToggle>
          )}
        </>
      )}

      {showInlineSection && showHeadingsSection && (
        <Separator orientation="vertical" className="mx-1 h-6" />
      )}

      {showHeadingsSection && (
        <>
          <ToolbarToggle
            pressed={editorState.isHeading1}
            disabled={!editorState.canHeading1}
            onPressedChange={() =>
              editor.chain().focus().toggleHeading({ level: 1 }).run()
            }
            title="Heading 1"
          >
            <Heading1 className="size-4" />
          </ToolbarToggle>
          <ToolbarToggle
            pressed={editorState.isHeading2}
            disabled={!editorState.canHeading2}
            onPressedChange={() =>
              editor.chain().focus().toggleHeading({ level: 2 }).run()
            }
            title="Heading 2"
          >
            <Heading2 className="size-4" />
          </ToolbarToggle>
          <ToolbarToggle
            pressed={editorState.isHeading3}
            disabled={!editorState.canHeading3}
            onPressedChange={() =>
              editor.chain().focus().toggleHeading({ level: 3 }).run()
            }
            title="Heading 3"
          >
            <Heading3 className="size-4" />
          </ToolbarToggle>
        </>
      )}

      {(showInlineSection || showHeadingsSection) && showBlockSection && (
        <Separator orientation="vertical" className="mx-1 h-6" />
      )}

      {showBlockSection && (
        <>
          {!hideBulletList && (
            <ToolbarToggle
              pressed={editorState.isBulletList}
              disabled={!editorState.canBulletList}
              onPressedChange={() =>
                editor.chain().focus().toggleBulletList().run()
              }
              title="Bullet list"
            >
              <List className="size-4" />
            </ToolbarToggle>
          )}
          {!hideOrderedList && (
            <ToolbarToggle
              pressed={editorState.isOrderedList}
              disabled={!editorState.canOrderedList}
              onPressedChange={() =>
                editor.chain().focus().toggleOrderedList().run()
              }
              title="Ordered list"
            >
              <ListOrdered className="size-4" />
            </ToolbarToggle>
          )}
          {!hideBlockquote && (
            <ToolbarToggle
              pressed={editorState.isBlockquote}
              disabled={!editorState.canBlockquote}
              onPressedChange={() =>
                editor.chain().focus().toggleBlockquote().run()
              }
              title="Blockquote"
            >
              <Quote className="size-4" />
            </ToolbarToggle>
          )}
          {!hideHorizontalRule && (
            <ToolbarButton
              onClick={() => editor.chain().focus().setHorizontalRule().run()}
              disabled={!editorState.canHorizontalRule}
              title="Horizontal rule"
            >
              <Minus className="size-4" />
            </ToolbarButton>
          )}
        </>
      )}

      {(showInlineSection || showHeadingsSection || showBlockSection) &&
        showUndoRedoSection && (
          <Separator orientation="vertical" className="mx-1 h-6" />
        )}

      {showUndoRedoSection && (
        <>
          <ToolbarButton
            onClick={() => editor.chain().focus().undo().run()}
            disabled={!editorState.canUndo}
            title="Undo"
          >
            <Undo className="size-4" />
          </ToolbarButton>
          <ToolbarButton
            onClick={() => editor.chain().focus().redo().run()}
            disabled={!editorState.canRedo}
            title="Redo"
          >
            <Redo className="size-4" />
          </ToolbarButton>
        </>
      )}
    </div>
  );
}

